<?= $this->extend('layout') ?><?= $this->section('content') ?><h1>Staff Accounts</h1><a class="button" href="<?= site_url('users/new') ?>">Add Staff Member</a><section class="card"><table><thead><tr><th>Avatar</th><th>Username</th><th>Full Name</th><th>Created At</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $user): $avatar=!empty($user['avatar'])?basename($user['avatar']):'placeholder.svg'; ?><tr><td><img class="thumb" src="<?= base_url('uploads/avatars/'.rawurlencode($avatar)) ?>" alt="Avatar of <?= esc($user['full_name']) ?>"></td><td><?= esc($user['username']) ?></td><td><?= esc($user['full_name']) ?></td><td><?= esc($user['created_at']) ?></td><td><a href="<?= site_url('users/'.$user['id'].'/edit') ?>">Edit</a> <form class="inline" method="post" action="<?= site_url('users/'.$user['id'].'/delete') ?>"><?= csrf_field() ?><button class="danger">Delete / Archive</button></form></td></tr><?php endforeach ?></tbody></table></section><?= $this->endSection() ?>
